-- Call deferral ("call me next week / next month").
--
-- Hand-written rather than generated by `prisma migrate dev`: migration
-- 20260622000000_session_campaigns contains Postgres `CREATE TYPE ... AS ENUM`, which SQLite
-- cannot execute, so history cannot be replayed into a shadow database. That migration is already
-- applied to the live DB and is deliberately left alone; this one is applied with `migrate deploy`,
-- which uses no shadow DB.
--
-- SessionCallStatus.deferred and DropdownAction.defer_calling need no DDL — Prisma stores enums as
-- TEXT on SQLite, so new values are a schema-level change only.
--
-- All three columns are additive and nullable (or defaulted), so existing rows are untouched and
-- older server builds keep working against this schema.

-- The deferral date lives on the batch roster, not on session_call_assignments: assignments are
-- scoped to a single campaign and the caller queue only reads active campaigns, so a one-month
-- deferral would vanish when its session completed.
ALTER TABLE "batch_members" ADD COLUMN "snooze_until" DATETIME;
ALTER TABLE "batch_members" ADD COLUMN "snooze_count" INTEGER NOT NULL DEFAULT 0;

-- Interval carried by the option itself, so retitling a label never silently changes its meaning.
ALTER TABLE "dropdown_options" ADD COLUMN "defer_days" INTEGER;

-- Queue reads filter on "is this person snoozed right now", per centre/batch.
CREATE INDEX IF NOT EXISTS "batch_members_snooze_until_idx" ON "batch_members"("snooze_until");
